import re

def parse_json(text):
    pos = [0]
    def space():
        while pos[0] < len(text) and text[pos[0]].isspace():
            pos[0] += 1
    def read_string():
        pos[0] += 1
        out = []
        while pos[0] < len(text):
            ch = text[pos[0]]
            pos[0] += 1
            if ch == '"':
                return ''.join(out)
            if ch == '\\':
                esc = text[pos[0]]
                pos[0] += 1
                escapes = {'"': '"', '\\': '\\', '/': '/', 'b': '\b', 'f': '\f', 'n': '\n', 'r': '\r', 't': '\t'}
                if esc == 'u':
                    out.append(chr(int(text[pos[0]:pos[0] + 4], 16)))
                    pos[0] += 4
                else:
                    out.append(escapes[esc])
            else:
                out.append(ch)
        raise ValueError('Invalid JSON string')
    def read_value():
        space()
        ch = text[pos[0]]
        if ch == '"':
            return read_string()
        if ch == '[':
            pos[0] += 1
            result = []
            space()
            if text[pos[0]] == ']':
                pos[0] += 1
                return result
            while True:
                result.append(read_value())
                space()
                ch = text[pos[0]]
                pos[0] += 1
                if ch == ']':
                    return result
        if ch == '{':
            pos[0] += 1
            result = {}
            space()
            if text[pos[0]] == '}':
                pos[0] += 1
                return result
            while True:
                space()
                key = read_string()
                space()
                pos[0] += 1
                result[key] = read_value()
                space()
                ch = text[pos[0]]
                pos[0] += 1
                if ch == '}':
                    return result
        if text.startswith('true', pos[0]):
            pos[0] += 4
            return True
        if text.startswith('false', pos[0]):
            pos[0] += 5
            return False
        if text.startswith('null', pos[0]):
            pos[0] += 4
            return None
        match = re.match(r'-?(?:0|[1-9][0-9]*)(?:\.[0-9]+)?(?:[eE][+-]?[0-9]+)?', text[pos[0]:])
        if not match:
            raise ValueError('Invalid JSON value')
        token = match.group(0)
        pos[0] += len(token)
        return float(token) if any(c in token for c in '.eE') else int(token)
    return read_value()

