def solve(inputs, readings):
    payments = inputs['payments']
    weights = inputs['weights']
    split = readings['split']

    entries = []
    for line in payments.splitlines():
        if not line.strip():
            continue
        name, amount = line.split('|', 1)
        name = name.strip()
        amount = amount.strip()
        whole, fraction = amount.split('.', 1)
        cents = int(whole) * 100 + int(fraction[:2].ljust(2, '0'))
        entries.append((name, cents))

    if isinstance(weights, str):
        weight_map = {name: int(value) for name, value in re.findall(r'"([^"]+)"\s*:\s*(-?\d+)', weights)}
    else:
        weight_map = weights

    total = sum(amount for name, amount in entries)
    count = len(entries)
    if split == 'equal':
        shares = [(2 * total + count) // (2 * count) for name, amount in entries]
    else:
        weight_sum = sum(int(weight_map[name]) for name, amount in entries)
        shares = [(2 * total * int(weight_map[name]) + weight_sum) // (2 * weight_sum) for name, amount in entries]

    balances = [(name, amount - share) for (name, amount), share in zip(entries, shares)]
    most_owed = max(balances, key=lambda item: item[1])
    most_owing = min(balances, key=lambda item: item[1])

    def money(cents):
        return '{}.{:02d}'.format(cents // 100, cents % 100)

    return '{} | total {} | most owed {} {} | most owing {} {}'.format(
        split,
        money(total),
        most_owed[0], money(abs(most_owed[1])),
        most_owing[0], money(abs(most_owing[1]))
    )

