            whole, fraction = amount.split('.', 1)
        else:
            whole, fraction = amount, '0'
        cents = int(whole) * 100 + int((fraction + '00')[:2])
        payments.append((name, cents))

    total = sum(cents for name, cents in payments)
    weights = inputs['weights']

    def round_half_up(numerator, denominator):
        return (2 * numerator + denominator) // (2 * denominator)

    balances = []
    if split == 'equal':
        share = round_half_up(total, len(payments))
        for name, paid in payments:
            balances.append((name, paid - share))
    else:
        weight_total = sum(weights[name] for name, paid in payments)
        for name, paid in payments:
            share = round_half_up(total * weights[name], weight_total)
            balances.append((name, paid - share))

    owed_index = 0
