        if balances[i][1] < balances[owing_index][1]:
            owing_index = i

    def format_amount(cents):
        cents = abs(cents)
        return str(cents // 100) + '.' + str(cents % 100).zfill(2)

    owed_name, owed_balance = balances[owed_index]
    owing_name, owing_balance = balances[owing_index]
    return split + ' | total ' + format_amount(total) + ' | most owed ' + owed_name + ' ' + format_amount(owed_balance) + ' | most owing ' + owing_name + ' ' + format_amount(owing_balance)

